import csv,collections
rows=list(csv.DictReader(open('responses.csv')))
agg=collections.defaultdict(list)
for r in rows: agg[(r['number_set'],int(r['target']))].append(int(r['rating']))
sets=collections.defaultdict(dict)
for (s,t),v in agg.items(): sets[s][t]=v
for s,d in sets.items():
  ex=[int(x) for x in s.split(',')]
  if len(ex)<2: continue
  digs=[c for c in '0123456789' if all(c in str(x) for x in ex)]
  if not digs: continue
  ends={x%10 for x in ex}
  out=[]
  for t,v in sorted(d.items()):
    if t in ex: continue
    if any(c in str(t) for c in digs) and t%10 not in ends:
      out.append(f'{t}:{sum(v)}/{len(v)}')
  if out: print(s,digs,' '.join(out))
"

